import * as THREE from 'three';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
import {ColladaLoader} from 'three/addons/loaders/ColladaLoader.js';
import {applyUrdfOrigin as applyOrigin,applyJointAngle} from './kinematics.js';

export async function createViewer(container,model,onPick){
 const renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0x101622,0);renderer.outputColorSpace=THREE.SRGBColorSpace;container.append(renderer.domElement);renderer.domElement.setAttribute('aria-label','JAX V2 로봇 3D 모델. 드래그로 시점 회전, 휠로 확대합니다. 관절 연결은 오른쪽 선택창에서도 설정할 수 있습니다.');
 const scene=new THREE.Scene();const camera=new THREE.PerspectiveCamera(40,1,.001,100);const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.dampingFactor=.08;controls.minDistance=.25;controls.maxDistance=7;
 scene.add(new THREE.HemisphereLight(0xe6f0ff,0x253044,2.8));const light=new THREE.DirectionalLight(0xffffff,3);light.position.set(3,5,4);scene.add(light);const rim=new THREE.DirectionalLight(0x6c8fff,2);rim.position.set(-2,2,-2);scene.add(rim);
 const grid=new THREE.GridHelper(3,30,0x40516d,0x263247);grid.material.transparent=true;grid.material.opacity=.55;scene.add(grid);const axes=new THREE.AxesHelper(.17);axes.position.set(-.5,.002,.4);scene.add(axes);
 const loader=new ColladaLoader();const assets=new Map();let loaded=0;const files=[...new Set(model.links.flatMap(l=>l.visuals.map(v=>v.file)))];await Promise.all(files.map(async file=>{const asset=await loader.loadAsync(`./models/jax/${file}`);/* ColladaLoader converts Z_UP to Y_UP; URDF already supplies its own Z-up frame. */asset.scene.quaternion.identity();assets.set(file,asset.scene);loaded++;document.getElementById('model-loading').textContent=`로봇 모델을 불러오는 중… ${loaded} / ${files.length}`;}));
 const movable=model.joints.filter(j=>j.type!=='fixed');const markers=[];
 function makeRobot(target){const root=new THREE.Group();root.rotation.x=-Math.PI/2;const links=new Map(),rotations=new Map(),meshes=new Map();for(const link of model.links){const group=new THREE.Group();group.name=link.name;links.set(link.name,group);const visualMeshes=[];for(const visual of link.visuals){const frame=new THREE.Group();applyOrigin(frame,visual);frame.scale.fromArray(visual.scale);const mesh=assets.get(visual.file).clone(true);mesh.traverse(node=>{if(node.isMesh){node.material=new THREE.MeshStandardMaterial({color:target?0x3b82f6:0xb5c0d1,roughness:.62,metalness:.35,transparent:target,opacity:target?.28:1,depthWrite:!target,side:THREE.DoubleSide});node.renderOrder=target?2:0;visualMeshes.push(node);}});frame.add(mesh);group.add(frame);}meshes.set(link.name,visualMeshes);}
 for(const joint of model.joints){const frame=new THREE.Group();applyOrigin(frame,joint);const rotation=new THREE.Group();frame.add(rotation);rotation.add(links.get(joint.child));links.get(joint.parent).add(frame);rotations.set(joint.name,rotation);if(!target&&joint.type!=='fixed'){const marker=new THREE.Mesh(new THREE.SphereGeometry(.012,16,12),new THREE.MeshBasicMaterial({color:0x65738a,transparent:true,opacity:.85,depthTest:false}));marker.userData.joint=joint.name;marker.renderOrder=5;frame.add(marker);markers.push(marker);}}
 const children=new Set(model.joints.map(j=>j.child));for(const link of model.links)if(!children.has(link.name))root.add(links.get(link.name));scene.add(root);return {root,rotations,meshes};}
 const actual=makeRobot(false),target=makeRobot(true);let motors=[],selectedName='',mode='both';const bounds=new THREE.Box3().setFromObject(actual.root);const size=bounds.getSize(new THREE.Vector3());const center=bounds.getCenter(new THREE.Vector3());if(!Number.isFinite(size.length())||size.length()>15||size.length()<.01)throw Error('모델 크기를 확인할 수 없습니다.');grid.position.y=bounds.min.y-.004;
 function reset(){controls.target.copy(center);const distance=Math.max(size.length()*1.65,1.2);camera.position.copy(center).add(new THREE.Vector3(distance*.85,distance*.45,distance*.85));camera.near=distance/1000;camera.far=distance*100;camera.updateProjectionMatrix();controls.update();}reset();
 function update(nextMotors,selection){motors=nextMotors;selectedName=selection;for(const joint of movable){const motor=motors.find(m=>m.joint===joint.name);const actualAngle=motor?.type==='ak'&&motor.scenario!=='offline'?motor.current:0;const targetAngle=motor?motor.draft:0;applyJointAngle(actual.rotations.get(joint.name),joint.axis,actualAngle);applyJointAngle(target.rotations.get(joint.name),joint.axis,targetAngle);const selected=motor?.name===selectedName;for(const mesh of actual.meshes.get(joint.child)){mesh.material.color.set(selected?0xaaa7ff:motor?.type==='ak'?0xcbd5e1:0x65738a);mesh.material.emissive.set(selected?0x292453:0x000000);}for(const mesh of target.meshes.get(joint.child)){mesh.material.color.set(selected?0x8183ff:0x3b82f6);mesh.material.opacity=selected?.5:.25;}const marker=markers.find(m=>m.userData.joint===joint.name);marker.material.color.set(selected?0xb7b4ff:motor?0x8183ff:0x52617a);marker.scale.setScalar(selected?1.5:1);}}
 function setMode(value){mode=value;actual.root.visible=mode!=='target';target.root.visible=mode!=='actual';/* Keep joint markers accessible in target-only mode without displaying the actual geometry. */}
 const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();const tooltip=document.getElementById('joint-tooltip');let start=null;
 function hit(event){const rect=renderer.domElement.getBoundingClientRect();pointer.set((event.clientX-rect.left)/rect.width*2-1,-(event.clientY-rect.top)/rect.height*2+1);raycaster.setFromCamera(pointer,camera);const visibleRoot=mode==='target'?target:actual;const objects=raycaster.intersectObject(visibleRoot.root,true);const markerHits=mode==='target'?[]:raycaster.intersectObjects(markers);if(markerHits.length)return markerHits[0].object.userData.joint;const meshHit=objects.find(o=>o.object.isMesh&&!o.object.userData.joint);if(!meshHit)return null;let node=meshHit.object;while(node){const joint=movable.find(j=>j.child===node.name);if(joint)return joint.name;node=node.parent;}return null;}
 renderer.domElement.addEventListener('pointerdown',event=>{start={x:event.clientX,y:event.clientY};});renderer.domElement.addEventListener('pointerup',event=>{if(!start||Math.hypot(event.clientX-start.x,event.clientY-start.y)>5)return;const joint=hit(event);if(joint){const motor=motors.find(m=>m.joint===joint);if(motor)onPick(motor.name);else onPick(null,joint);}start=null;});
 renderer.domElement.addEventListener('pointermove',event=>{const joint=hit(event);if(!joint){tooltip.hidden=true;renderer.domElement.style.cursor='grab';return;}const motor=motors.find(m=>m.joint===joint);tooltip.textContent=motor?`${motor.name} · ${joint}`:`${joint} · 모터 미연결 (선택 불가)`;tooltip.hidden=false;const rect=container.getBoundingClientRect();tooltip.style.left=`${Math.min(event.clientX-rect.left+12,Math.max(10,rect.width-270))}px`;tooltip.style.top=`${Math.min(event.clientY-rect.top+15,rect.height-60)}px`;renderer.domElement.style.cursor=motor?'pointer':'help';});renderer.domElement.addEventListener('pointerleave',()=>tooltip.hidden=true);
 const resize=new ResizeObserver(()=>{const {width,height}=container.getBoundingClientRect();renderer.setSize(width,height);camera.aspect=width/height;camera.updateProjectionMatrix();});resize.observe(container);renderer.setAnimationLoop(()=>{controls.update();renderer.render(scene,camera);});return {update,setMode,reset};
}
